class AccountDto {
  final BigInt userId;
  final String nickname;
  final String? avatarUrl;
  final bool active;
  final bool vip;

  const AccountDto({
    required this.userId,
    required this.nickname,
    this.avatarUrl,
    required this.active,
    required this.vip,
  });

  @override
  int get hashCode =>
      userId.hashCode ^
      nickname.hashCode ^
      avatarUrl.hashCode ^
      active.hashCode ^
      vip.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AccountDto &&
          runtimeType == other.runtimeType &&
          userId == other.userId &&
          nickname == other.nickname &&
          avatarUrl == other.avatarUrl &&
          active == other.active &&
          vip == other.vip;
}

