/// 没有 subscribedCount(收藏数) 与 hotCount(热门评论数) —— 别在 UI 里显示这两个.
class CommentStats {
  /// 评论线程 id(R_SO_4_/A_PL_0_/R_AL_3_/A_DJ_1_/R_VI_62_…)
  final String threadId;

  /// 资源 id
  final BigInt resourceId;

  /// 评论总数
